public class InnerGatewayTargetHttpTargetConfigurationFactory(Action<Humidifier.BedrockAgentCore.GatewayTargetTypes.HttpTargetConfiguration> factoryAction = null) : SubResourceFactory<Humidifier.BedrockAgentCore.GatewayTargetTypes.HttpTargetConfiguration>
{

    internal InnerGatewayTargetHttpConnectorTargetConfigurationFactory ConnectorFactory { get; set; }

    internal InnerGatewayTargetPassthroughTargetConfigurationFactory PassthroughFactory { get; set; }

    internal InnerGatewayTargetRuntimeTargetConfigurationFactory AgentcoreRuntimeFactory { get; set; }

    protected override Humidifier.BedrockAgentCore.GatewayTargetTypes.HttpTargetConfiguration Create()
    {
        var httpTargetConfigurationResult = CreateHttpTargetConfiguration();
        factoryAction?.Invoke(httpTargetConfigurationResult);

        return httpTargetConfigurationResult;
    }

    private Humidifier.BedrockAgentCore.GatewayTargetTypes.HttpTargetConfiguration CreateHttpTargetConfiguration()
    {
        var httpTargetConfigurationResult = new Humidifier.BedrockAgentCore.GatewayTargetTypes.HttpTargetConfiguration();

        return httpTargetConfigurationResult;
    }
    public override void CreateChildren(Humidifier.BedrockAgentCore.GatewayTargetTypes.HttpTargetConfiguration result)
    {
        base.CreateChildren(result);

        result.Connector ??= ConnectorFactory?.Build();
        result.Passthrough ??= PassthroughFactory?.Build();
        result.AgentcoreRuntime ??= AgentcoreRuntimeFactory?.Build();
    }

} // End Of Class

